(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["zu"] = {"ui":{"skip":"Yeqela ukuya okuqukethwe","back":"← Buyela ku-AI-gile","lang.button":"Ulimi: {name}","lang.dialog":"Khetha ulimi","lang.search":"Sesha izilimi","lang.none":"Alukho ulimi oluhambisanayo","lang.notYet":"{name} alukahunyushwa okwamanje","theme.aria":"Shintsha phakathi kwetimu ekhanyayo nemnyama","theme.toLight":"Shintshela etimini ekhanyayo","theme.toDark":"Shintshela etimini emnyama","index.title":"AI-gile: iqembu lakho le-AI lokuthuthukisa, ebhodini elilodwa","index.description":"I-AI-gile yibhodi le-kanban lamaqembu e-AI abhala ikhodi. Asebenza ngenkathi ulele; wena uthola inqwaba emfushane yezinto zokuthatha isinqumo, ukuhlola nokwamukela.","hero.logoAlt":"Isithonjana sebhodi le-AI-gile","hero.h1.html":"Iqembu lakho le-AI lokuthuthukisa, ebhodini&nbsp;elilodwa.","hero.alpha":"🐣 I-pre-alpha evaliwe","hero.alphaTitle":"Kusenesikhathi futhi akukaqedwa: siyabonga ngokuzama!","hero.lede":"Akha ngenkathi ulele. Uvuka kunqwaba emfushane eyodwa: imibuzo embalwa, izinto ezimbalwa zokuhlola, idayimane elilodwa noma amabili ansomi. Chofoza, yamukela, ubuyele ekhofini lakho.","dl.windows":"Uhlelo lwe-Windows","dl.browser":"Lusebenzise kusiphequluli sakho","dl.soon":"Kuyeza maduze","dl.notify":"🔔 Ngazise lapho livulwa","dl.notifySmall":"I-alpha noma i-beta","hero.secondary":"I-agile, kodwa iqembu alidingi ikhofi le-stand-up. (Nokho liyazenza ama-stand-up.)","pitch.h2":"I-AI-gile ngamagama amaningi noma amancane njengoba ufuna","pitch.lede":"Khetha ubude, kusukela egameni elilodwa kuya kwangu-144. Ubude ngabunye buyincazelo yabo, ebhalelwe leso silinganiso. Donsa isilayidi noma sebenzisa imicibisholo.","pitch.rangeLabel":"Ubude ngamagama","pitch.dice":"🎲 enye inguqulo","pitch.words.one":"igama elingu-{n}","pitch.words.other":"amagama angu-{n}","pitch.letters.one":"uhlamvu olungu-{n}","pitch.letters.other":"izinhlamvu ezingu-{n}","pitch.chars.one":"uhlamvu olungu-{n}","pitch.chars.other":"izinhlamvu ezingu-{n}","count.line.html.one":"ikhadi elingu-{n} ebhodini khona manje","count.line.html.other":"amakhadi angu-{n} ebhodini khona manje","features.aria":"Okwenzayo","f.pile.h":"Inqwaba eyodwa yakho","f.pile.html":"<b>Kuwe</b> iqoqe konke okukulindele kuwo wonke amaphrojekthi: imibuzo, izinto zokuhlola, imisebenzi umuntu kuphela ayenzayo. Ulayini wakho ukutshela ukuthi yini elandelayo nokuthi kuthatha isikhathi esingakanani.","f.sleep.h":"Amaqembu asebenza ulele","f.sleep.p":"Iphrojekthi ngayinye inomholi neqembu lama-ejenti e-AI. Phawula ekhadini futhi iqembu liyavuka, lenze umsebenzi, liwubuyisele nezinyathelo umuntu ozikhathele angazilandela.","f.tester.h":"Umhloli we-AI uhlola kuqala","f.tester.p":"Ngaphambi kokuba kukufinyelele, umhloli ulandela izinyathelo kukhophi yohlelo bese ekukhombisa ayekubonile, ngesithombe-skrini. Hlola ngokushesha okwedlulile bese wamukela ngokuchofoza kanye.","f.proof.h":"Ubufakazi, hhayi izithembiso","f.proof.p":"Ukudluliselwa ngakunye kukhombisa okushintshile: amafayela, umahluko, izithombe-skrini. Akudingeki uvule uhlelo ngalunye ukuze ubone ukuthi sekuphelile yini.","f.chat.h":"Xoxa nabaholi bakho","f.chat.p":"Umugqa ofana nowe-Discord: isithonjana esisodwa kuphrojekthi ngayinye, amadayimane ansomi kokudinga wena. Thumela umholi umbono; bayiguqulela emakhadini nasepulanini, nenkinobho ethi ✅ Qala.","f.tidy.h":"Iziqoqa ngokwayo","f.tidy.p":"Amakhadi ahlobene ayahlangana abe linye, izihloko ezididayo ziyalungiswa, futhi ukuhlolwa kwamathokheni kugcina ikhodi incane. Izinto ezimbalwa zokushintsha phakathi kwazo, okuncane ongacabanga ngakho.","f.private.h":"Kungokwakho, ekhompyutheni yakho","f.private.li1":"Ibhodi lisebenza emshinini wakho futhi lilandela wena kuphela.","f.private.li2":"Imilayezo eyimfihlo phakathi kwabantu ibethelwe isuka ekugcineni iye ekugcineni.","f.private.li3":"Awekho ama-akhawunti, awekho ama-tracker, awekho amakhukhi.","f.lang.h":"Ngolimi lwakho","f.lang.p":"Izilimi ezingaphezu kwekhulu namashumi amabili, kusukela esiDashi, isiWelsh nesiJapane kuya umphangi wasolwandle, isiYoda nesiKlingon, nokushintsha ngokushesha kubuyele esiNgisini emagameni abathuthukisi.","tl.aria":"Isikhathi esisukela engxoxweni yokuqala kuya emgwaqweni wesikhathi esizayo","tl.h2":"Kusukela engxoxweni yokuqala kuya kokulandelayo","tl.lede":"Amadethi nezikhathi zangempela, ngesikhathi sendawo yakho. Ngemva kwanamuhla kuyisu, akukho madethi aqinisekisiwe.","tl.today":"Namuhla","tl.planned":"kuhlelwe","tl.cards.one":"ikhadi elingu-{n}","tl.cards.other":"amakhadi angu-{n}","join.h2":"Joyina","join.lede":"I-AI-gile yakhiwa umuntu omncane kanye nenqwaba yama-ejenti anesineke. Okwamanje iyimfihlo, kuyi-alpha evaliwe nabangani. Ungathanda ukuzama lapho ivuleka?","join.btn":"Bhalisa isithakazelo","join.small":"Sizokubhalela nge-imeyili, akukho okunye","footer.tag":"I-AI-gile. Awekho ama-tracker, awekho amakhukhi, awekho ikhofi le-stand-up.","footer.licence":"Ilayisense yebhizinisi","footer.status":"Isimo","form.sending":"Iyathumela…","form.failed":"Akusebenzanga: zama futhi emuva kwesikhathi.","form.offline":"Asikwazanga ukufinyelela ku-AI-gile: zama futhi emuva kwesikhathi.","interest.title":"I-AI-gile: ngazise lapho i-alpha ivulwa","interest.description":"Shiya i-imeyili yakho ukuze uzwe lapho i-alpha noma i-beta evaliwe ye-AI-gile ivulwa.","interest.h1":"🔔 Ngazise lapho livulwa","interest.lede":"I-AI-gile iku-pre-alpha evaliwe. Shiya i-imeyili yakho futhi sizobhala kanye kuphela, lapho kunendawo yakho.","interest.email":"I-imeyili yakho","interest.which":"Ukuhlolwa kuphi?","interest.alpha":"I-alpha evaliwe: ekuqaleni, ayikaphelele, ushintsho oluningi","interest.beta":"I-beta: iqinile kakhulu, kamuva","interest.both":"Noma iyiphi, nanoma iyiphi eza kuqala","interest.submit":"Ngifake ohlwini","interest.thanks":"Siyabonga! Usohlwini.","interest.kept":"Kugcinwa kuphela i-imeyili yakho nokuhlolwa okukhethile, kuleli hlelo kuphela. Alikho ileta yezindaba, awekho ama-tracker.","licence.title":"I-AI-gile: ilayisense yebhizinisi","licence.description":"Usebenzisa i-AI-gile ebhizinisini lakho? Faka isicelo selayisense yebhizinisi mahhala.","licence.h1":"📜 Ilayisense yebhizinisi","licence.lede":"Usebenzisa i-AI-gile emsebenzini? Sitshele ukuthi ungubani nokuthi wenzani. Uma kwenza okuhle, ilayisense ayibizi lutho.","licence.company":"Inkampani","licence.website":"Iwebhusayithi","licence.what":"Okwenzayo","licence.how":"Ikusiza kanjani umhlaba","licence.email":"I-imeyili","licence.submit":"Faka isicelo","licence.thanks":"Siyabonga! Sizophendula nge-imeyili.","status.title":"Isimo se-AI-gile","status.h1":"Isimo se-AI-gile","status.quiet":"Konke kuthule","status.checking":"Iyahlola…","status.offline":"Asikwazi ukufinyelela insizakalo yesimo okwamanje (iyazama futhi)","status.updated":"ibuyekezwe {ago}","status.justNow":"khona manje","status.min":"imizuzu engu-{n} edlule","status.hours":"amahora angu-{n} edlule","status.days":"izinsuku ezingu-{n} edlule","live.h2":"Bukela ngenkathi yakhiwa, bukhoma","live.caption":"Wonke ikhadi lifihliwe: ubona isimo somsebenzi, hhayi amagama.","live.watching.one":"bukhoma: {n} uyabuka","live.watching.other":"bukhoma: {n} bayabuka","live.offline":"Ibhodi elibukhoma lithatha ikhefu elifushane. Buya maduze.","live.cols":"Backlog|Okufanele kwenziwe|Kuyaqhubeka|Iqembu liyahlola|Kuwe ukuthi test|Kweqembu|Kuphelile"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Amarobhothi.","Nikeza."]},{"n":2,"texts":["Kanban yamarobhothi.","Ama-ejenti, ahlelekile.","Imibono, yakhiwe."]},{"n":3,"texts":["Ibhodi lamarobhothi lamahhala.","Imibono iba izici.","Kanban yama-ejenti, mahhala."]},{"n":5,"texts":["Ibhodi eliqhutshwa ngama-ejenti, lamahhala nje.","Wena ubhala amakhadi. Ama-ejenti akha.","Mahhala, ekhaya, ihloliwe, nenhlanhla encane."]},{"n":8,"texts":["Ibhodi le-kanban lamahhala lapho ama-ejenti e-AI asebenza khona.","Bhala umbono. Ama-ejenti awakhe. Wena uyawamukela.","I-agile yomuntu oyedwa namarobhothi amaningi anesineke nje."]},{"n":13,"texts":["Ibhodi le-kanban ekhompyutheni yakho lapho ama-ejenti e-AI athatha khona amakhadi.","Bhala umbono wakho. Iqembu lama-ejenti liyawakha lapho. Bese umhloli we-AI uyawuhlola ngemva kwalokho.","Mahhala, awekho ama-akhawunti, awekho ama-tracker: ibhodi, amarobhothi athile, wena nguwe oyinhloko."]},{"n":21,"texts":["I-AI-gile yibhodi le-kanban lokusebenza nama-ejenti e-AI abhala ikhodi. Wona athatha amakhadi bese wena uwahlola futhi uwamukele ngokwakho lapho eseqedile.","Iphrojekthi ngayinye ithola umholi kanye neqembu lama-ejenti e-AI. Phawula noma yiliphi ikhadi, bese iqembu liyavuka liqale ukusebenza ngokushesha okukhulu.","Yibhodi lemisebenzi yomuntu siqu, lamahhala, elisebenza ekhompyutheni yakho uqobo. Abasebenzi bangamarobhothi nje. Futhi ophendula ngokuthi yebo nguwe wedwa."]},{"n":34,"texts":["Ubeka imibono yakho ebhodini. Iqembu lama-ejenti e-AI liyiguqula ibe yizici ezisebenzayo, liyazihlola, bese liziletha kuwe nezinyathelo zokuzama. Akukho okubalwa njengokuphelile ngaphandle kokuthi wena uthi kunjalo. Konke kwenzeka ekhompyutheni yakho.","I-AI-gile yibhodi le-kanban elenziwe ekhaya, elakhiwa nguRich ngosizo olukhulu lwama-ejenti manje alawulwa yilo. Lamahhala, lisebenza ekhompyutheni yakho, futhi labelwana nabangani, alithengiswa muntu. Lakhelwe ukusiza nokujabulisa, akukho okunye okufihliwe nhlobo.","Cabanga ibhodi le-kanban elijwayelekile, namakholomu asuka ku-Backlog aze afike ku-Done, kodwa amakhadi athathwa ama-ejenti e-AI. Abika inqubekela phambili, abuza lapho ebambekile, futhi njalo alinde ukuvuma kwakho, uthi yebo noma cha."]},{"n":55,"texts":["I-AI-gile yibhodi le-kanban lapho iqembu lakhiwe ngama-ejenti e-AI. Iphrojekthi ngayinye inomholi ohlela umsebenzi, nabasizi abawakhayo. Uma isici sesilungile, umhloli we-AI uyasizama, athathe nesithombe-skrini, bese sifika enqwabeni yakho. Ungasamukela, noma uphawule bese iqembu liqala kabusha ukusebenza ngokukhulu ukunaka. Konke kulula futhi kucacile, ngakho ungabuyela ekhofini lakho.","Laqala njengendlela yomuntu oyedwa yokulandelela izikhathi eziningi zokubhala ikhodi nge-AI ngasikhathi sinye, laze lakhula laba yibhodi langempela. Lisebenza emshinini wakho, alidingi i-akhawunti, futhi alinawo ama-tracker. Lamahhala kubangani nakuwo wonke onelukuluku. Alikaphelele, ngakho lindela ubukhali obuthile nezimanga ezimbalwa ngezikhathi ezithile. Kungcono ukuqala kancane, kanjalo siyakhula ndawonye nabangani.","Nanku iqiniso eliqinile. Kusadingeka ube nemibono yakho, futhi kusadingeka uhlole imiphumela ngokwakho. I-AI-gile yenza konke okuphakathi: igcina amakhadi ehleleke kahle, ivusa i-ejenti efanele uma uphawula, ikhombisa ncamashi okushintshile, futhi ikubeka konke enqwabeni eyodwa emfushane eyakho kuphela. Ukucabanga nokukhetha kusalokhu kungokwakho, futhi lokho kunjalo ngenhloso."]},{"n":89,"texts":["I-AI-gile yibhodi le-kanban lamahhala olisebenzisa ekhompyutheni yakho uqobo. Esikhundleni sabantu, iphrojekthi ngayinye inalo iqembu lama-ejenti e-AI: umholi oguqula imibono yakho ibe amakhadi nepulani, nabasizi abathatha amakhadi ngokulandelana kokubaluleka. Uma okuthile sekwakhiwe, umhloli we-AI ulandela izinyathelo zokuhlola bese ekukhombisa lokho akubonile ngesithombe-skrini. Bese kulinda enqwabeni eyodwa ethi Kuwe. Uyakwamukela, noma uphawule bese iqembu lizama futhi kusukela ekuqaleni. Akukho nakanye okufika ku-Done ngaphandle kwakho wena. Wonke umsebenzi wenzeka ekhompyutheni yakho, futhi awudingi i-akhawunti ukuze uwusebenzise.","Ezinye izici ongase ungazilindele. Umqaphi wasebusuku ugcina ikholomu ethi To do igcwele ngenkathi ulele, ekhetha amakhadi angadingi mpendulo evela kuwe. Isibali samathokheni sikhombisa ukuthi ama-ejenti asebenzise malini namuhla nalesi sonto, futhi imodi ethi No Token Mode iwatshela ukuba ayeke ukusebenzisa. Ungathumela imilayezo kubangani, futhi imilayezo eyimfihlo ibethelwe ngokuphelele. Ibhodi likhuluma izilimi ezingaba ngu-120, kubandakanya isiDashi, isiFlemish, umphangi wasolwandle nesiKlingon. Akukho kulokhu okubiza lutho, futhi akekho ozama ukukudayisela lona. Konke lokhu kwenzelwe ukuba ulale kahle, wazi ukuthi umsebenzi uqhubeka.","I-AI-gile iyiphrojekthi encane, yomuntu siqu, hhayi inkampani. URich wayefuna ukunakekela amaphrojekthi amaningi e-AI ngaphandle kokuvula uhlelo ngalunye ukuze alihlole, ngakho yena nama-ejenti akha ibhodi, base besebenzisa lona ibhodi ukwakha okusele kwalo uqobo. Iku-pre-alpha evaliwe, okusho ukuthi isebenza, ikakhulukazi, kwabangani abambalwa kuphela. Alikho ikhasi lamanani, alikho ileta yezindaba, futhi alikho icebo lokukhula. Uma lizwakala linomsebenzi kuwe, ungacela ukulizama lapho livuleka kancane nje. Uma ufuna ukuzama, bhala nje ukucela, bese sikuphendula ngokushesha uma sesikulungele kahle."]},{"n":144,"texts":["I-AI-gile yibhodi le-kanban lomuntu oyedwa nama-ejenti amaningi e-AI. Lisebenza ekhompyutheni yakho uqobo futhi lamahhala ngokuphelele. Wengeza amaphrojekthi, futhi iphrojekthi ngayinye ithola umholi neqembu elincane. Uxoxa nomholi, kufana kakhulu ne-Discord, uchaze umbono wakho; umholi uwuguqulela emakhadini nasepulanini, bese elinda ukuthi ucindezele u-Qala. Iqembu lisebenza ngamakhadi ngokulandelana kokubaluleka, lisebenzisa umugqa wemiyalo olula owenzelwe amamodeli olimi. Ngaphambi kokuba kukubuyele, umhloli we-AI ulandela izinyathelo kukhophi yohlelo bese enamathisela isithombe-skrini. Umsebenzi oqediwe uwela enqwabeni yakho kanye namafayela ashintshile nomahluko wawo. Uyawamukela, noma ushiye isikhumbuzo bese iqembu livuka lizame futhi. Wena kuphela ongashintshela ikhadi ku-Done, akekho omunye. Konke okwenziwayo kuyabonakala, ngakho awudingi ukuthemba ngokungaboni. Ibhodi lilula, linesineke, futhi lihlala lilinde izinqumo zakho ngokuthula okukhulu. Kuphelele kumuntu ofuna ukunyakazisa umsebenzi ngaphandle kokuhlala kuwo usuku lonke.","Usuku ne-AI-gile, kafushane. Kusihlwa uphawula amazwana ambalwa: le nkinobho isendaweni engafanele, lolo hlu kufanele luhlelwe, ingabe singaba nemodi emnyama yini. Uyalala. Ama-ejenti afunda amazwana, enze izinguquko, azihlole, bese ezibuyisela kuwe. Uma ikholomu ethi To do iphela, umqaphi wasebusuku uyigcwalisa evela ku-backlog ngamakhadi angadingi mpendulo evela kuwe. Ekuseni kunenqwaba eyodwa emfushane: imibuzo embalwa nezinto ezimbalwa zokuzama, ngayinye inezinyathelo umuntu onokulala angazilandela kanye nesithombe-skrini sokuthi isebenza. Uchofoza ngazo ngayinye, wamukele ezinhle bese uthumela ezisele emuva ukuze zilungiswe. Isibali samathokheni sikhombisa ukuthi konke kusebenzise malini, futhi imodi ethi No Token Mode ikhona ezinsukwini zokonga. Bese udla ibhulakufesi, okungakasizi ngakho ama-ejenti. Ngesonto elilandelayo ungenza okufanayo, uphinde ubone ukuthi kuthatha isikhathi esingakanani. Awudingi ukuhlala usuku lonke ubheke isikrini, futhi ibhodi lihlala lilungele wena.","Okokuqala, ukuthi i-AI-gile ayiyona yini. Akuyona inkampani entsha, akuthengiswa, futhi akekho oqoqa idatha yakho. Yibhodi lamahhala elisebenza ekhompyutheni yakho, ngaphandle kwama-akhawunti, ngaphandle kwama-tracker nangaphandle kwamakhukhi. Yini yona: indawo eyodwa ehlelekile yokubona wonke amaphrojekthi e-AI ngasikhathi sinye, neqembu lama-ejenti enza amakhadi nawe uthatha izinqumo. Ihlanganisa amakhadi ahlobene, ilungisa izihloko ezididayo, futhi ibheka ukuthi ikhodi ihlala incane kangakanani. Ikhuluma izilimi ezingaba ngu-120, kusukela esiDashi nesiFlemish kuya kumphangi wasolwandle nesiKlingon. Abangani bangathumelana imilayezo, ngasese futhi ibethelwe. Yakhiwe nguRich nenqwaba yama-ejenti anesineke, ikakhulukazi isebenzisa yona ngokwayo. Iku-pre-alpha evaliwe, ngakho inobukhali kwezinye izindawo. Uma kuzwakala kumnandi, cela kahle futhi ungangena kusenesikhathi. Kuyibhodi elincane elinenhliziyo, elenzelwe ukuba lisize abantu abangenaso isikhathi sokuhlola konke ngabo ngokwabo. Futhi kungumsebenzi oqhubekayo, kusakhula nsuku zonke."]}],"quips":{"1":"Igama elilodwa. Lilukhuni. Mhlawumbe lilukhuni kakhulu.","3":"Amagama amathathu. Seliqinisile kunamakhasi amaningi emikhiqizo.","8":"Amagama ayisishiyagalombili. Kusamfushane kuno-stand-up.","21":"Ubude bungamaphoyinti ezindaba, ngendlela. Yebo, kunjalo.","55":"Amagama angamashumi amahlanu nanhlanu. Amakhadi amabili aphelile ngenkathi ufunda lokho.","144":"Lena yinde. Alikho elingu-233. Ama-ejenti aye ukulala."}},"timeline":{"first-idea.name":"Umbono wokuqala","first-idea.line":"Ingxoxo yokuqala nya, ngaphambi kokuba kube khona ikhodi.","first-board.name":"Ibhodi lokuqala","first-board.line":"Ibhodi elilandelela ukwakhiwa kwalo: amakhadi, amakholomu, donsa uphonse, amaphrojekthi.","team-roles.name":"Iqembu nezindima","team-roles.line":"Amaphrofayela ama-ejenti, amathempulethi eqembu, izikhala nokuthi ngubani owenzani.","install.name":"Ukufaka nokukhishwa","install.line":"I-zip umngani angayifaka, ukuzibuyekeza, amashaneli nokubuyela emuva.","usage-saver.name":"Ukonga ukusetshenziswa","usage-saver.line":"Linganisa izindleko zokusebenza, gcina ikhodi incane, onge umkhawulo wakho.","friends.name":"Abangani nokwabelana","friends.line":"Imilayezo eyimfihlo, isidlulisi esixubekile, izimemo, izindima namaphrojekthi abelwanayo.","languages.name":"Izilimi","languages.line":"Yonke imibhalo yesikrini ifayelini lolimi, kuqala ngesiDashi nesiFlemish.","ai-tester.name":"Umhloli we-AI","ai-tester.line":"Umhloli uhlola ukudluliselwa ngakunye kuqala bese ekhombisa ayekubonile.","website.name":"Iwebhusayithi","website.line":"I-aigile.lol, i-teaser nalesi sikhathi.","streaming.name":"Ingxoxo nokusakaza","streaming.line":"I-Discord, i-Twitch, i-OBS, imodi yomsakazi, ama-GIF nama-emoji.","no-ai.name":"Uhlelo olungenayo i-AI","no-ai.line":"Ibhodi labantu abakhipha ikhodi ngaphandle kwe-AI, namabhodi omphakathi.","night-watch.name":"Ukuqapha ebusuku","night-watch.line":"Umqaphi ne-Scrum Master baqhubekisa amaqembu emsebenzini ngenkathi ulele.","p-more.name":"Konke okunye","p-more.line":"Imibono emincane ekhona isalindele ithuba layo.","p-android.name":"Ifoni ne-Android","p-android.line":"Finyelela ibhodi lakho ofonini, bese kuba uhlelo lwangempela lwe-Android.","p-release.name":"I-alpha nangale kwayo","p-release.line":"I-alpha evaliwe, isayithi eliphilayo, bese i-beta.","p-languages.name":"Izilimi eziningi","p-languages.line":"Izilimi ezingaphezu kwekhulu, nemodi yokucwiliswa yabafundi.","p-engines.name":"Izinjini ze-AI eziningi","p-engines.line":"Khetha i-Claude, i-Codex noma i-Gemini ku-ejenti ngayinye.","p-pro.name":"Umkhuba wochwepheshe","p-pro.line":"Amalebula obungozi, amasango okuhlanganisa, amakhadi ezehlakalo nezivikelo.","p-self.name":"Ukukunakekela","p-self.line":"Imodi yokukhathala, izikhumbuzi zokuzinakekela ne-4:20.","p-servers.name":"Amaseva nobukhulu","p-servers.line":"Izilungiselelo zamaseva jikelele, izindima nokuhlela ukukhula.","p-livestream.name":"Okungeziwe kokusakaza","p-livestream.line":"Ingxoxo ye-Twitch, ama-emoji ngokwezifiso nombono womphakathi ophilayo."}};
